RELEASED_ON_FRAME = 90

#: Diagonal of the cart's centroid extent over the slice. Under
#: LINK_STATIC_SPREAD_PX, so `_is_parked` is true and the no-taker parked branch
#: is the release path.
CART_CENTROID_SPAN_PX = 11.2

